use vstd::prelude::*;
use vstd::slice::*;
use vstd::vec::*;

verus! {

spec fn is_even(x: i32) -> bool {
    x % 2 == 0
}

spec fn contains_even_values(slice: &[i32]) -> bool {
    forall|i: int| 0 <= i < slice.len() ==> is_even(slice[i])
}

spec fn all_even_values_present(input: &[i32], output: &[i32]) -> bool {
    forall|i: int| 
        0 <= i < input.len() && is_even(input[i]) ==> 
        exists|j: int| 0 <= j < output.len() && output[j] == input[i]
}

fn remove_odd_numbers(arr: &[i32]) -> (result: Vec<i32>)
    ensures
        // All elements in result are even
        forall|i: int| 0 <= i < result.len() ==> is_even(result[i]),
        // All even values from input appear in result
        all_even_values_present(arr, result.as_slice()),
        // All elements in result come from input
        forall|i: int| 0 <= i < result.len() ==> 
            exists|j: int| 0 <= j < arr.len() && arr[j] == result[i],
{
    let mut result_vec = Vec::new();
    let mut idx: usize = 0;
    
    while idx < arr.len()
        invariant
            0 <= idx <= arr.len(),
            // All elements added so far are even
            forall|i: int| 0 <= i < result_vec.len() ==> is_even(result_vec[i]),
            // All even values from processed portion appear in result
            forall|j: int| 0 <= j < idx && is_even(arr[j]) ==>
                exists|k: int| 0 <= k < result_vec.len() && result_vec[k] == arr[j],
            // All elements in result come from processed portion of input
            forall|i: int| 0 <= i < result_vec.len() ==> 
                exists|j: int| 0 <= j < idx && arr[j] == result_vec[i],
        decreases arr.len() - idx,
    {
        let elem = arr[idx];
        if elem % 2 == 0 {
            result_vec.push(elem);
        }
        idx = idx + 1;
    }
    
    result_vec
}

#[verifier(external)]
fn main() {
    let test1 = vec![1, 2, 3, 4, 5, 6];
    let result1 = remove_odd_numbers(&test1);
    println!("Input: {:?}, Result: {:?}", test1, result1);
    
    let test2 = vec![];
    let result2 = remove_odd_numbers(&test2);
    println!("Input: {:?}, Result: {:?}", test2, result2);
    
    let test3 = vec![1, 3, 5, 7];
    let result3 = remove_odd_numbers(&test3);
    println!("Input: {:?}, Result: {:?}", test3, result3);
    
    let test4 = vec![2, 4, 6, 8];
    let result4 = remove_odd_numbers(&test4);
    println!("Input: {:?}, Result: {:?}", test4, result4);
}

} // verus!